def load_config(environment):
    value = environment.get('PROGRESS_STORAGE')
    if not value:
        raise ValueError('PROGRESS_STORAGE must be configured')
    return {'storage_name': value, 'request_timeout_seconds': 10}

assert load_config({'PROGRESS_STORAGE': 'progress-records'})['storage_name'] == 'progress-records'
try:
    load_config({})
except ValueError:
    pass
else:
    raise AssertionError('missing setting should fail')

